import { describe, expect, it } from 'vitest'
import { modelNameFromProviderId, translate } from './translate'
import { createFusionProvider, PRIMARY_GRACE_MS } from './providers/llm/fusion'
import type { LlmProvider, LlmTranslationContent } from './providers/llm'
import type { DictionaryProvider } from './providers/dictionary'
import type { TranslationCache } from './cache/translationCache'

// "AI-generated by <model>" footnote: which model wrote an entry.

const HELLO: LlmTranslationContent = {
  headword: 'hello',
  meaningGroups: [{ partOfSpeech: 'interjection', senses: [{ definition: 'A greeting' }] }],
}

const dictionary: DictionaryProvider = { id: 'dict:test', define: async () => [] }

function provider(id: string, content: LlmTranslationContent | null, delayMs = 0, onPartial = false): LlmProvider {
  return {
    id,
    async translate(_req, opts) {
      if (onPartial) opts?.onPartial?.(content ?? HELLO)
      if (delayMs) await new Promise((r) => setTimeout(r, delayMs))
      if (!content) throw new Error(`${id} failed`)
      return { content }
    },
    async moreExamples() {
      return { examples: [] }
    },
  }
}

function recordingCache() {
  const sets: Array<{ entries: Array<{ generatedBy?: unknown }> }> = []
  const cache: TranslationCache = {
    async get() {
      return null
    },
    async set(_w, _s, _t, entries) {
      sets.push({ entries: entries as never })
    },
  }
  return { cache, sets }
}

let seq = 0
const req = () => ({ text: `gen${(seq += 1)}`, sourceLang: 'en', targetLang: 'en' })

async function settle(): Promise<void> {
  for (let i = 0; i < 20; i++) await new Promise((r) => setTimeout(r, 5))
}

describe('modelNameFromProviderId', () => {
  it('strips the llm:<vendor>: prefix and keeps colons inside model ids', () => {
    expect(modelNameFromProviderId('llm:openrouter:openai/gpt-6-luna')).toBe('openai/gpt-6-luna')
    expect(modelNameFromProviderId('llm:deepseek:deepseek-v4-flash')).toBe('deepseek-v4-flash')
    expect(modelNameFromProviderId('llm:openrouter:meta/llama:free')).toBe('meta/llama:free')
    expect(modelNameFromProviderId('weird')).toBe('weird')
  })
})

describe('translate — generatedBy', () => {
  it('stamps a single provider’s model on served and cached entries', async () => {
    const { cache, sets } = recordingCache()
    const outcome = await translate(req(), provider('llm:anthropic:claude-haiku-5-5', HELLO), dictionary, cache)
    expect(outcome.tier).toBe('llm')
    expect(outcome.entries[0].generatedBy).toEqual({ models: ['claude-haiku-5-5'] })
    await settle()
    expect(sets[0].entries[0].generatedBy).toEqual({ models: ['claude-haiku-5-5'] })
  })

  it('fusion: the first answer credits the winning model; the cached merge credits both', async () => {
    const fusion = createFusionProvider({
      primary: provider('llm:openrouter:openai/gpt-6-luna', HELLO, 30),
      secondary: provider('llm:deepseek:deepseek-v4-flash', HELLO, 0),
    })
    const { cache, sets } = recordingCache()
    const outcome = await translate(req(), fusion, dictionary, cache)
    expect(outcome.entries[0].generatedBy).toEqual({ models: ['deepseek-v4-flash'] })
    await settle()
    const last = sets[sets.length - 1].entries[0]
    expect(last.generatedBy).toEqual({ models: ['openai/gpt-6-luna', 'deepseek-v4-flash'], merged: true })
  })

  it('fusion: credits the primary when it wins the grace period after streaming to the user', async () => {
    const fusion = createFusionProvider({
      primary: provider('llm:openrouter:openai/gpt-6-luna', HELLO, 30, true),
      secondary: provider('llm:deepseek:deepseek-v4-flash', HELLO, 0),
    })
    const outcome = await translate(req(), fusion, dictionary, null, { onPartial: () => {} })
    expect(PRIMARY_GRACE_MS).toBeGreaterThan(30)
    expect(outcome.entries[0].generatedBy).toEqual({ models: ['openai/gpt-6-luna'] })
  })

  it('fusion: when one side fails, credits the survivor and keeps it (no merged upgrade)', async () => {
    const fusion = createFusionProvider({
      primary: provider('llm:openrouter:openai/gpt-6-luna', null),
      secondary: provider('llm:deepseek:deepseek-v4-flash', HELLO, 5),
    })
    const { cache, sets } = recordingCache()
    const outcome = await translate(req(), fusion, dictionary, cache)
    expect(outcome.entries[0].generatedBy).toEqual({ models: ['deepseek-v4-flash'] })
    await settle()
    expect(sets.every((s) => (s.entries[0].generatedBy as { merged?: boolean }).merged !== true)).toBe(true)
  })

  it('dictionary-tier entries carry no generatedBy', async () => {
    const dict: DictionaryProvider = {
      id: 'dict:test',
      define: async () => [{ word: 'hello', phonetics: [], meanings: [] }],
    }
    const outcome = await translate(req(), null, dict, null)
    expect(outcome.tier).toBe('dictionary')
    expect(outcome.entries[0]).not.toHaveProperty('generatedBy')
  })
})
